// Turns one event from the database into one short chat message.
const body = $input.first().json.body ?? {};
const event = String(body.event ?? 'unknown');
const d = body.data ?? {};
const n = v => Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 });
const clean = v => String(v ?? '').replace(/[\r\n]+/g, ' ').slice(0, 200);
let text;
switch (event) {
  case 'signup': text = ':new: New player: **' + clean(d.name) + '**'; break;
  case 'big_win': text = ':moneybag: Big win: **' + clean(d.name) + '** won ' + n(d.payout) + ' coins on ' + clean(d.game) + ' (' + n(d.multiplier) + 'x, bet ' + n(d.amount) + ')'; break;
  case 'adjustment': text = ':warning: Coins added by hand: **' + clean(d.name) + '** +' + n(d.amount) + ' (balance now ' + n(d.balance_after) + ')'; break;
  case 'admin': text = ':lock: Admin action: ' + clean(d.action) + ' by ' + clean(d.actor) + ' (' + clean(d.role) + ')' + (d.reason ? ' - ' + clean(d.reason) : ''); break;
  case 'maintenance': text = (d.on ? ':tools: Maintenance is ON' : ':white_check_mark: Maintenance is OFF') + (d.message ? ': ' + clean(d.message) : ''); break;
  case 'test': text = ':white_check_mark: Test message from the Vaultrush database'; break;
  default: text = 'Vaultrush event "' + clean(event) + '": ' + clean(JSON.stringify(d)).slice(0, 500);
}
return [{ json: { message: text.slice(0, 1900) } }];
